            kwargs["text"] = text

        if prompt.tools:
            kwargs["tools"] = [
                {
                    "type": "function",
                    "name": tool.name,
                    "description": tool.description or None,
                    "parameters": tool.input_schema,
                }
                for tool in prompt.tools
            ]

